(function(){"use strict";app.factory("proveedorService",function(e){const t="Compra/Proveedor/",o={},r=e.get("mainService");return o.get=function(e){const o={...e,tipo:1};return r.getData("get",`${t}?json=${JSON.stringify(o)}`,null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let{proveedores:t}=JSON.parse(e.payload);return t}})},o.getDataForm=function(){let e={tipo:3};return r.getData("get",`${t}?json=${JSON.stringify(e)}`,null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let{tiposIdentificacion:t,subcontribuyentes:o,tiemposCredito:r,tiposEntidad:n,tiposProveedor:i,ciudades:a}=JSON.parse(e.payload);return{tiposIdentificacion:t,subcontribuyentes:o,tiemposCredito:r,tiposEntidad:n,tiposProveedor:i,ciudades:a}}})},o.getId=function(e){let o={id:e,tipo:2};return r.getData("get",`${t}?json=${JSON.stringify(o)}`,null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let t=JSON.parse(e.payload),o=t.proveedor[0];return{...o,correos:o.correo?o.correo.split(";"):[],telefonos:o.telefonos?o.telefonos.split(";"):[]}}})},o.search=function(e){let o={textSearch:e,tipo:5};return r.getData("get",`${t}?json=${JSON.stringify(o)}`,null,!0).then(e=>{if("0"===e.code)return console.log(e),[];if("1"===e.code){let t=JSON.parse(e.payload),o=t.proveedores;return o.map(e=>({...e,nombreFiscal:e.razonSocial}))}})},o.checkByID=function(e){let o={tipo:4,identificacion:e};return r.getData("get",`${t}?json=${JSON.stringify(o)}`,null,!0).then(e=>{if(console.log(e),"0"===e.code)return{idProveedor:0,idTiempoCredito:0};if("1"===e.code){let t=JSON.parse(e.payload);return t.proveedor}})},o.post=function(e){return r.getData("post",`${t}`,{data:e},!0)},o.put=function(e,o){return r.getData("put",`${t}${e}`,{data:o},!0)},o.delete=function(e){return r.getData("delete",t+e,null,!0)},o}),app.factory("categoriaCompraService",function(e){const t="Compra/CategoriaCompra/",o=e.get("mainService"),r={get:e=>o.getData("get",t+"?json="+JSON.stringify(e),null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let t=JSON.parse(e.payload);return t}}),post:e=>o.getData("post",t+"?json="+JSON.stringify(e),null,!0),put:(e,r)=>o.getData("put",t+e+"?json="+JSON.stringify(r),null,!0),delete:e=>o.getData("delete",t+""+e,null,!0)};return r})})(window.angular);